# app/frontend/evaluation.py
# Page 2: how the model was evaluated. The charts are the ones in
# reports/figures, generated by `python -m src.cross_validate` and
# `python run.py`, so this page always shows the evaluated model.

import json
from pathlib import Path

import streamlit as st

PROJECT_ROOT = Path(__file__).resolve().parents[2]
FIGURES = PROJECT_ROOT / "reports" / "figures"
METADATA = PROJECT_ROOT / "models" / "model_metadata.json"

# From src/build_dataset.py: 385 patients in the raw data, of whom 32 were
# already in ICU in the 0-2 hour window and are excluded.
RAW_PATIENTS = 385
EXCLUDED_ALREADY_IN_ICU = 32

FIGURES_SHOWN = [
    "cv_model_comparison.png",
    "calibration_before_after.png",
    "threshold_tradeoff.png",
    "cm_test.png",
]


def show_figure(name, caption):
    path = FIGURES / name
    if path.exists():
        st.image(str(path), width="stretch")
        st.caption(caption)
    else:
        st.warning(f"Figure not found: reports/figures/{name}. Run the training pipeline to create it.")


def cohort_diagram(metadata):
    train = metadata["training_split"]
    test = metadata["test"]
    n_model = train["n_patients"] + test["n_patients"]
    n_icu = train["n_icu"] + test["n_icu"]

    return f"""
    digraph {{
        rankdir=LR;
        bgcolor="transparent";
        node [shape=box, style="rounded,filled", fillcolor="#f4f3f0", color="#d4d2cc",
              fontname="Helvetica", fontsize=11, margin="0.15,0.08"];
        edge [color="#8f8d87"];
        raw   [label="{RAW_PATIENTS} patients\\n5 time windows each"];
        excl  [label="{EXCLUDED_ALREADY_IN_ICU} excluded\\nalready in ICU at 0-2 h", fillcolor="#fde3d8"];
        model [label="{n_model} patients\\n{n_icu} later admitted to ICU\\n{n_model - n_icu} never admitted"];
        train [label="Training split: {train['n_patients']}\\n({train['n_icu']} ICU)\\nmodel choice, threshold", fillcolor="#e6f0fc"];
        test  [label="Test split: {test['n_patients']}\\n({test['n_icu']} ICU)\\nused once, at the end", fillcolor="#e6f0fc"];
        raw -> excl;
        raw -> model;
        model -> train;
        model -> test;
    }}
    """


st.title("📊 How the model was evaluated")

st.markdown(
    "Every chart on this page is produced by the project's training pipeline "
    "and committed with the model, so it always describes the model behind the "
    "risk estimate. Details: "
    "[README](https://github.com/Firas-Armoush-ai/icu-covid19-prediction#modeling-and-evaluation)."
)

st.subheader("1. Which patients were used")
try:
    st.graphviz_chart(cohort_diagram(json.loads(METADATA.read_text())))
    st.caption(
        "Patients already in ICU during the first two hours were excluded: their measurements "
        "may have been taken after admission, which would leak the outcome into the features."
    )
except (OSError, KeyError, ValueError):
    st.warning("Model metadata not found, so the patient numbers can't be shown.")

st.subheader("2. Comparing models")
show_figure(
    "cv_model_comparison.png",
    "Repeated cross-validation on the training split only. The differences between models are "
    "small next to the spread across folds, and a model that uses only the age group does as well: "
    "in the first two hours, most of the signal is age.",
)

st.subheader("3. Making the probabilities trustworthy")
show_figure(
    "calibration_before_after.png",
    "The raw random forest gave extreme probabilities that didn't match how often patients went to "
    "ICU. Sigmoid calibration brings them close to the diagonal, so an estimate of 40% means about "
    "40% of similar patients needed ICU.",
)

st.subheader("4. Choosing the decision threshold")
show_figure(
    "threshold_tradeoff.png",
    "Missing a patient who needs ICU is the costliest error, so the threshold is set to catch 90% of "
    "them on the training data. The chart shows the price: the more patients it must catch, the more "
    "patients it flags.",
)

st.subheader("5. The single test on held-out patients")
show_figure(
    "cm_test.png",
    "The test patients were held out from every step above and used once. With this few patients the "
    "results are uncertain; the README gives 95% intervals.",
)
